const poetryLock1 = `[[package]]
name = "requests"
version = "2.19.0"
category = "main"

[[package]]
name = "pytest"
version = "7.0.0"
category = "dev"

[[package]]
name = "py"
version = "1.11.0"
category = "dev"

[metadata]
lock-version = "1.1"
`

func TestPoetryLockParser(t *testing.T) {
	for name, tc := range map[string]struct {
		lock string
		want map[string][2]bool
	}{
		"poetry2-groups": {poetryLock2, map[string][2]bool{
			"attrs@26.1.0":    {false, true},
			"jinja2@2.10":     {true, false},
			"pytest@7.0.0":    {true, true},
			"requests@2.19.0": {true, false},
			"urllib3@1.23":    {false, false}, // in main and dev → production
		}},
		"poetry1-category": {poetryLock1, map[string][2]bool{
			"requests@2.19.0": {true, false},
			"pytest@7.0.0":    {true, true},
			"py@1.11.0":       {false, true},
		}},
	} {
		t.Run(name, func(t *testing.T) {
			root := writeFiles(t, map[string]string{"pyproject.toml": poetryPyproject, "poetry.lock": tc.lock})
			res, err := PoetryLockParser{}.Parse(filepath.Join(root, "poetry.lock"), "poetry.lock")
			if err != nil {
				t.Fatal(err)
			}
			checkPyComponents(t, res.Components, tc.want)
		})
	}
}

