func TestUvLockParser(t *testing.T) {
	root := writeFiles(t, map[string]string{"uv.lock": uvLockSample})
	res, err := UvLockParser{}.Parse(filepath.Join(root, "uv.lock"), "uv.lock")
	if err != nil {
		t.Fatal(err)
	}
	checkPyComponents(t, res.Components, map[string][2]bool{
		"attrs@26.1.0":     {false, true}, // only reachable via pytest
		"jinja2@2.10":      {true, false},
		"markupsafe@3.0.4": {false, false}, // via jinja2 (production)
		"pytest@7.0.0":     {true, true},
		"requests@2.19.0":  {true, false},
		"urllib3@1.23":     {false, false}, // reachable from both → production
		"celery@5.0.0":     {true, false},  // direct dep of a workspace member
	})
}

func checkPyComponents(t *testing.T, got []Component, want map[string][2]bool) {
	t.Helper()
	m := byName(got)
	if len(m) != len(want) {
		t.Errorf("want %d components, got %d: %v", len(want), len(m), m)
	}
	for key, flags := range want {
		c, ok := m[key]
		if !ok {
			t.Errorf("%s missing", key)
			continue
		}
		if c.Direct != flags[0] || c.Dev != flags[1] || c.Ecosystem != EcosystemPyPI {
			t.Errorf("%s: direct=%v dev=%v eco=%s, want direct=%v dev=%v", key, c.Direct, c.Dev, c.Ecosystem, flags[0], flags[1])
		}
	}
}

func TestPyLockParsers_InvalidTOML(t *testing.T) {
	root := writeFiles(t, map[string]string{"poetry.lock": "[[package]\nname=", "uv.lock": "version = "})
	if _, err := (PoetryLockParser{}).Parse(filepath.Join(root, "poetry.lock"), "poetry.lock"); err == nil {
		t.Error("poetry: expected error")
	}
	if _, err := (UvLockParser{}).Parse(filepath.Join(root, "uv.lock"), "uv.lock"); err == nil {
		t.Error("uv: expected error")
	}
}

func TestReadPyDeclared_Styles(t *testing.T) {
	const pep621 = `[project]
dependencies = ["Requests[socks]>=2.0; python_version>'3'", "flask"]

[project.optional-dependencies]
docs = ["sphinx==7.0"]

[dependency-groups]
dev = ["pytest>=7", {include-group = "lint"}, "flask"]
lint = ["ruff"]

[tool.poetry.dev-dependencies]
black = "*"
`
	root := writeFiles(t, map[string]string{"pyproject.toml": pep621})
	d := pyDeclared(readPyproject(filepath.Join(root, "uv.lock")))
	for _, n := range []string{"requests", "flask", "sphinx", "pytest", "ruff", "black"} {
		if !d.direct[n] {
			t.Errorf("%s should be direct", n)
		}
	}
	for n, dev := range map[string]bool{"requests": false, "flask": false, "sphinx": false, "pytest": true, "ruff": true, "black": true} {
		if d.dev[n] != dev {
			t.Errorf("%s dev=%v want %v", n, d.dev[n], dev)
		}
	}
}

func TestParsePEP508(t *testing.T) {
	cases := map[string]PyRequirement{
		"requests==2.19.0":                      {Name: "requests", Spec: "==2.19.0"},
		"Jinja2 >= 2.10 ; python_version > '3'": {Name: "jinja2", Spec: ">= 2.10", Marker: "; python_version > '3'"},
		"uvicorn[standard]>=0.20,<1":            {Name: "uvicorn", Extras: "[standard]", Spec: ">=0.20,<1"},
		"zope.interface":                        {Name: "zope-interface"},
		"pkg @ https://example.com/pkg-1.0.whl": {Name: "pkg", Spec: "@ https://example.com/pkg-1.0.whl", URL: true},
	}
	for in, want := range cases {
		got, ok := ParsePEP508(in)
		if !ok || got != want {
			t.Errorf("ParsePEP508(%q) = %+v, %v; want %+v", in, got, ok, want)
		}
	}
	if _, ok := ParsePEP508("  "); ok {
		t.Error("blank should not parse")
	}
}

func TestParsePyproject_OrderAndSections(t *testing.T) {
	const src = `[project]
dependencies = ["requests==2.19.0"]

[project.optional-dependencies]
docs = ["sphinx~=7.0"]

[dependency-groups]
dev = ["pytest==7.0.0", {include-group = "lint"}]

[tool.poetry.dependencies]
python = "^3.10"
celery = { version = "^4.0", markers = "sys_platform != 'win32'" }

[tool.poetry.group.main.dependencies]
attrs = "^23"

[tool.poetry.dev-dependencies]
black = "*"

[tool.uv]
dev-dependencies = ["ruff==0.1.0"]
`
	reqs, err := ParsePyproject([]byte(src))
	if err != nil {
		t.Fatal(err)
	}
	var got []string
	for _, r := range reqs {
		got = append(got, r.Name+":"+string(r.Kind))
	}
	want := []string{
		"requests:project", "celery:poetry", "sphinx:optional", "attrs:poetry-group", // production first
		"pytest:group", "black:poetry-legacy-dev", "ruff:uv-legacy-dev",
	}
	if len(got) != len(want) {
		t.Fatalf("got %v", got)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("order:\n got %v\nwant %v", got, want)
		}
	}
	if !reqs[1].Table || reqs[2].Section != "docs" {
		t.Errorf("celery table=%v sphinx section=%q", reqs[1].Table, reqs[2].Section)
	}
	if _, err := ParsePyproject([]byte("[project\n")); err == nil {
		t.Error("invalid TOML should fail")
	}
}

func TestPyprojectCheck(t *testing.T) {
	cases := map[string]struct {
		files map[string]string
		warn  bool
	}{
		"deps without lock": {map[string]string{"pyproject.toml": poetryPyproject}, true},
		"with poetry.lock":  {map[string]string{"pyproject.toml": poetryPyproject, "poetry.lock": ""}, false},
		"with uv.lock":      {map[string]string{"pyproject.toml": poetryPyproject, "uv.lock": ""}, false},
		"with requirements": {map[string]string{"pyproject.toml": poetryPyproject, "requirements.txt": ""}, false},
		"tool config only":  {map[string]string{"pyproject.toml": "[tool.black]\nline-length = 100\n"}, false},
	}
	for name, tc := range cases {
		root := writeFiles(t, tc.files)
		res, _ := PyprojectCheck{}.Parse(filepath.Join(root, "pyproject.toml"), "pyproject.toml")
		if (len(res.Warnings) > 0) != tc.warn {
			t.Errorf("%s: warnings=%v want warn=%v", name, res.Warnings, tc.warn)
		}
	}
}

// Poetry 1.5–1.8 locks have neither category nor groups (review #6):
// dev status must come from the dependency graph.
const poetryLock18 = `[[package]]
name = "requests"
version = "2.19.0"
optional = false

[package.dependencies]
urllib3 = ">=1.21.1,<1.24"
PySocks = {version = ">=1.5.6", optional = true}

[package.extras]
socks = ["PySocks (>=1.5.6)"]

[[package]]
name = "pysocks"
version = "1.7.1"
optional = true

[[package]]
name = "urllib3"
version = "1.23"
optional = false

[[package]]
name = "pytest"
version = "7.0.0"
optional = false

[package.dependencies]
pluggy = ">=0.12,<2.0"
urllib3 = "*"

[[package]]
name = "pluggy"
version = "1.0.0"
optional = false

[metadata]
lock-version = "2.0"
`

func TestPoetryLockParser_NoGroupsUsesGraph(t *testing.T) {
	root := writeFiles(t, map[string]string{"pyproject.toml": poetryPyproject, "poetry.lock": poetryLock18})
	res, err := PoetryLockParser{}.Parse(filepath.Join(root, "poetry.lock"), "poetry.lock")
	if err != nil {
		t.Fatal(err)
	}
	checkPyComponents(t, res.Components, map[string][2]bool{
		"requests@2.19.0": {true, false},
		"urllib3@1.23":    {false, false}, // via requests (prod) and pytest (dev) → prod
		"pytest@7.0.0":    {true, true},
		"pluggy@1.0.0":    {false, true}, // only via pytest
		"pysocks@1.7.1":   {false, true}, // only via an extra nobody enables → not production
	})
}

// uv: optional dependencies of a package count only when a dependent
// enables that extra (review #7).
const uvLockExtras = `version = 1

[[package]]
name = "app"
version = "0.1.0"
source = { virtual = "." }
dependencies = [{ name = "httpx" }, { name = "requests", extra = ["socks"] }]

[package.dev-dependencies]
dev = [{ name = "pytest" }]

[[package]]
name = "httpx"
version = "0.27.0"
source = { registry = "https://pypi.org/simple" }

[package.optional-dependencies]
http2 = [{ name = "h2" }]

[[package]]
name = "h2"
version = "4.1.0"
source = { registry = "https://pypi.org/simple" }

[[package]]
name = "requests"
version = "2.32.0"
source = { registry = "https://pypi.org/simple" }

[package.optional-dependencies]
socks = [{ name = "pysocks" }]

[[package]]
name = "pysocks"
version = "1.7.1"
source = { registry = "https://pypi.org/simple" }

[[package]]
name = "pytest"
version = "8.0.0"
source = { registry = "https://pypi.org/simple" }
dependencies = [{ name = "httpx", extra = ["http2"] }]
`

func TestUvLockParser_ExtrasOnlyWhenEnabled(t *testing.T) {
	root := writeFiles(t, map[string]string{"uv.lock": uvLockExtras})
	res, err := UvLockParser{}.Parse(filepath.Join(root, "uv.lock"), "uv.lock")
	if err != nil {
		t.Fatal(err)
	}
	checkPyComponents(t, res.Components, map[string][2]bool{
		"httpx@0.27.0":    {true, false},
		"requests@2.32.0": {true, false},
		"pysocks@1.7.1":   {false, false}, // requests[socks] enabled by the project
		"h2@4.1.0":        {false, true},  // httpx[http2] enabled only by pytest (dev)
		"pytest@8.0.0":    {true, true},
	})
}
